def compute(vars):
    benefit_obligations = vars["v1"]
    capital_lease_obligations = vars["v2"]
    difference = benefit_obligations - capital_lease_obligations

    return {
        "value": difference,
        "trace": {
            "benefit_obligations": benefit_obligations,
            "capital_lease_obligations": capital_lease_obligations,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": "thousand",
                "unit": None
            }
        }
    }
